export function visualFeedbackSystem(feedbackData) {
  const canvas = document.getElementById('feedbackCanvas');
  const ctx = canvas.getContext('2d');
  feedbackData.forEach((loop, index) => {
    ctx.beginPath();
    ctx.arc(loop.x, loop.y, loop.radius, 0, 2 * Math.PI);
    ctx.fillStyle = loop.color;
    ctx.fill();
    ctx.stroke();
  });
}